import{_ as e,o as a,c as o,a4 as l}from"./chunks/framework.B0hSrcZ6.js";const r="/info/07-apps.webp",s="/info/07-apps-s2.webp",i="/info/07-apps-s3.webp",n="/info/07-apps-s4.webp",f=JSON.parse('{"title":"第 7 章 连接应用：插件、邮箱与 Secrets","description":"全面解析 Grok Bot 的应用与数据联动功能：详解通过 Vault 保险库自动填充登录与支付凭证、Bot 转发收件箱邮件并完整保留排版与附件技巧，并结合 Secrets 与连接器安全打通外部工作流。","frontmatter":{},"headers":[],"relativePath":"part1/07-apps.md","filePath":"part1/07-apps.md","lastUpdated":1792210948000}'),d={name:"part1/07-apps.md"};function c(h,t,p,g,u,b){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="第-7-章-连接应用-插件、邮箱与-secrets" tabindex="-1">第 7 章 连接应用：插件、邮箱与 Secrets <a class="header-anchor" href="#第-7-章-连接应用-插件、邮箱与-secrets" aria-label="Permalink to &quot;第 7 章 连接应用：插件、邮箱与 Secrets&quot;">​</a></h1><p>接入工具记住<strong>先跑通界面，再挂连接器</strong>。第三方密钥别往聊天框贴，<strong>存进 Secrets 只写存储</strong>防泄露。</p><ul><li>插件装太多会撑大上下文频繁报错；原生 X 检索免插件就能调用。</li><li>专属邮箱没收件箱界面也不弹窗，自动群发会卡在审批卡片。</li><li>企业环境注意 Zoom 报错、Google Workspace 拦截与机房 IP 风控。</li></ul><p><img src="'+r+'" alt="连接应用：插件、邮箱与 Secrets" width="1600" height="1013" decoding="async"></p><h2 id="接入顺序-先跑通界面-再挂连接器" tabindex="-1">接入顺序：先跑通界面，再挂连接器 <a class="header-anchor" href="#接入顺序-先跑通界面-再挂连接器" aria-label="Permalink to &quot;接入顺序：先跑通界面，再挂连接器&quot;">​</a></h2><h3 id="接入步骤" tabindex="-1">接入步骤 <a class="header-anchor" href="#接入步骤" aria-label="Permalink to &quot;接入步骤&quot;">​</a></h3><ol><li>界面操作：<strong>日常事务先在内置浏览器跑通</strong>。</li><li>官方连接器：稳定后接 Connect Apps 插件。</li><li>专用脚本：高频大吞吐最后调 API 或 CLI。</li></ol><h3 id="避坑与限制" tabindex="-1">避坑与限制 <a class="header-anchor" href="#避坑与限制" aria-label="Permalink to &quot;避坑与限制&quot;">​</a></h3><ul><li>全装会占上下文并引发调用幻觉。</li><li><strong>同账号 Bot 共享云电脑、浏览器与 <code>/workspace</code></strong>，建新 Bot 无法隔离凭据。</li></ul><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><p><strong>靠最小插件集准确完成任务</strong>，上下文无冗余工具声明与误触发。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/XDkUwLJZxih7Dok0SKqcajKQn4e" target="_blank" rel="noreferrer">《4.5 连接器、Skill、模板与对外入口》</a><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Qw17wVBhJibhkpkAK6zceiMvned" target="_blank" rel="noreferrer">《Grok Bot Masterclass｜Avi Chawla》</a></p><h2 id="插件连接-从商店授权到企业权限穿透" tabindex="-1">插件连接：从商店授权到企业权限穿透 <a class="header-anchor" href="#插件连接-从商店授权到企业权限穿透" aria-label="Permalink to &quot;插件连接：从商店授权到企业权限穿透&quot;">​</a></h2><p><img src="'+s+'" alt="插件连接：从商店授权到企业权限穿透" width="1600" height="1013" loading="lazy" decoding="async"></p><p>插件绑在个人账户且全局生效，<strong>权限受限于第三方平台，无法提权</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">插件</th><th style="text-align:left;">支持操作</th><th style="text-align:left;">限制与避坑</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Google Calendar</strong></td><td style="text-align:left;">读写日程、查空闲与回邀请</td><td style="text-align:left;">无法改 Meet 等候室；Zoom 需手动填链接</td></tr><tr><td style="text-align:left;"><strong>Google Drive</strong></td><td style="text-align:left;">检索与读取文件</td><td style="text-align:left;">改表格需配 Sheets；无法改分享名单</td></tr><tr><td style="text-align:left;"><strong>Google Sheets</strong></td><td style="text-align:left;">修改有权限单元格</td><td style="text-align:left;">只读文件不可改；检索由 Drive 处理</td></tr><tr><td style="text-align:left;"><strong>Slack</strong></td><td style="text-align:left;">频道发消息</td><td style="text-align:left;">进不去未加入的私有与禁言频道；非拉群 Bot</td></tr><tr><td style="text-align:left;"><strong>Gmail</strong></td><td style="text-align:left;">搜读发邮件、加标签</td><td style="text-align:left;">仅限单邮箱，个人与企业邮箱不可同绑</td></tr></tbody></table><p>详见<a href="https://cursor.com/cn/help/grok-bot/connect-plugins.md" target="_blank" rel="noreferrer">连接插件</a>。</p><ol><li>桌面端点侧边栏/聊天卡片「连接」，移动端点头像选「连接应用」。</li><li>搜插件点「添加」（Add）并在浏览器登录授权。</li><li>确认进入「已安装」（Installed）；中断点「重新连接」重试。</li></ol><p>企业 Google 遇拦截换浏览器无效，<strong>认证名为「Grok」</strong>。</p><p>管理员需在 Google Admin console 经 Security &gt; Access and data control &gt; API controls &gt; App access control &gt; Manage third-party app access 添加「Grok」（或填 Client ID）设为 Trusted。</p><p>提示「已被团队管理员禁用」联系 Cursor 管理员后台开启。</p><p><strong>在「已安装」列表无黄色警告，且能正常读数据、未触发 OAuth 失败即成功。</strong></p><h2 id="bot-专属邮箱-认领、收发规则与人闸审批" tabindex="-1">Bot 专属邮箱：认领、收发规则与人闸审批 <a class="header-anchor" href="#bot-专属邮箱-认领、收发规则与人闸审批" aria-label="Permalink to &quot;Bot 专属邮箱：认领、收发规则与人闸审批&quot;">​</a></h2><p><img src="'+i+'" alt="Bot 专属邮箱：认领、收发规则与人闸审批" width="1600" height="1013" loading="lazy" decoding="async"></p><p>Grok Bot 专属邮箱（<code>yourname@mail.grokbot.com</code>）<strong>归属个人账户</strong>。私聊与 Routines 可用，不可在 Slack 串或他人会话调用，无团队共享地址。</p><p>规则详见文档<a href="https://cursor.com/cn/help/grok-bot/agent-email.md" target="_blank" rel="noreferrer">为你的 Bot 设置电子邮箱地址</a>。</p><h3 id="使用限制与安全" tabindex="-1">使用限制与安全 <a class="header-anchor" href="#使用限制与安全" aria-label="Permalink to &quot;使用限制与安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>规则与限制</th></tr></thead><tbody><tr><td>地址属性</td><td>唯一且永久生效，<strong>无法重命名或删除</strong>，注销账号也不释放</td></tr><tr><td>发信配额</td><td>单封最多 50 人；附件最多 10 个（单个 ≤10MB，总量 ≤25MB，禁 <code>.exe</code>）</td></tr><tr><td>首次外联</td><td>限 1 位收件人且正文必带退订链接；退信或被标垃圾直接停用</td></tr><tr><td>收信安全</td><td><strong>无独立收件箱与通知</strong>，1 分钟后可查；内容只读，不执行指令</td></tr></tbody></table><h3 id="认领与配置" tabindex="-1">认领与配置 <a class="header-anchor" href="#认领与配置" aria-label="Permalink to &quot;认领与配置&quot;">​</a></h3><p>团队须管理员在后台（<code>cursor.com/dashboard/bot</code>）开启「Agent Email」，个人可直接用。地址限小写字母、数字及 <code>.-_</code>，首尾须为字母数字，最长 64 字符且避开保留词。</p><ol><li>认领地址：侧边栏进「Connect apps」&gt;「Email」创建，或发送 <code>claim your email</code> 及命令：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  给自己申请一个电子邮件地址</span></span></code></pre></div><ol start="2"><li>查询收信：对话中直接检索：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>今天你的收件箱里收到了什么？帮我找出过去一周收到的所有费用账单与回执。</span></span></code></pre></div><ol start="3"><li>配置例程：建 Routine 监听发件人（支持 <code>*@example.com</code>，不支持按主题筛选）：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收到来自 billing@example.com 的电子邮件时，总结其中的账单金额与截止日期，并将摘要整理后发送给我。</span></span></code></pre></div><ol start="4"><li>人闸审批：<strong>系统严禁无人值守静默外发</strong>。Bot 只生成草稿卡片，人工点击「Send」后才真正投递。</li></ol><h3 id="验收标准-1" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-1" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><p>外部发测试信后等待 1 分钟，让 Bot 查询并起草回复。<strong>屏幕弹出待审批卡片且点击前保持挂起</strong>即为成功。</p><h2 id="安全机密信息-secrets-的只写机制与团队隔离" tabindex="-1">安全机密信息：Secrets 的只写机制与团队隔离 <a class="header-anchor" href="#安全机密信息-secrets-的只写机制与团队隔离" aria-label="Permalink to &quot;安全机密信息：Secrets 的只写机制与团队隔离&quot;">​</a></h2><p><img src="'+n+`" alt="安全机密信息：Secrets 的只写机制与团队隔离" width="1600" height="1013" loading="lazy" decoding="async"></p><p><strong>敏感凭证绝不能发在对话框、写进 Shell 配置或录入「Teach a task」。</strong> 输入框保存后变空白是进入了保护状态。</p><p>云电脑执行 <code>Recover</code> 或 <code>Reset</code> 不会丢失凭证，详见<a href="https://cursor.com/cn/help/grok-bot/secrets.md" target="_blank" rel="noreferrer">安全存储机密信息</a>。</p><h3 id="提交与更新" tabindex="-1">提交与更新 <a class="header-anchor" href="#提交与更新" aria-label="Permalink to &quot;提交与更新&quot;">​</a></h3><ol><li>聊天提交：Bot 索取凭据时弹出安全卡片，输入框显示掩码，点「Save securely」，显示「Saved」即完成。</li><li>团队 Bot：在设置的「Secrets」点「Add secret」，填名称（如 <code>GITHUB_TOKEN</code>）、描述与密钥后点「Save secret」。<strong>更新点「Replace」与「Replace value」，系统不支持找回旧值。</strong></li><li>网页填入：若提示 <code>Could not fill into the page</code>，<strong>走 Takeover flow 手动接管登录</strong>，切忌在对话框发账号密码。</li></ol><h3 id="验收标准-2" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-2" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><ul><li><strong>面板仅显示名称与描述，密钥值完全隐藏。</strong></li><li>对话中要明文 Bot 读不到，但 CLI 或请求鉴权正常通过。</li></ul><h2 id="x-平台原生检索-免插件调用社交动态" tabindex="-1">X 平台原生检索：免插件调用社交动态 <a class="header-anchor" href="#x-平台原生检索-免插件调用社交动态" aria-label="Permalink to &quot;X 平台原生检索：免插件调用社交动态&quot;">​</a></h2><p>Grok Bot 在 v0.70.2（2026-10-08）集成了 X 只读检索。<strong>它直接走 The X Subscription 统一用量，不用装第三方插件，也不用配 API Token</strong>。</p><ol><li><strong>直接发自然语言指令</strong>：支持全网搜帖、抓取公开推文正文，也能查账号发帖与被 @ 记录，或统计特定话题 7 天互动趋势。</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检索 X 平台账号 @xai 最近 24 小时发布的所有推文。按时间倒序整理每条推文的核心内容、发布时间、点赞数、转推数，并附带原帖链接。</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检索 X 平台上关于 #AIagents 话题过去 7 天的热门讨论。筛选互动量最高的前 5 条推文，提取核心观点，并汇总该话题本周的讨论热度变化趋势。</span></span></code></pre></div><ol start="2"><li><strong>验收标准</strong>：<strong>结果要包含发布时间、互动数字与推文原链</strong>，全程没有连接器安装提示，也没有抓取截断。</li></ol><p>功能梳理见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/XDkUwLJZxih7Dok0SKqcajKQn4e" target="_blank" rel="noreferrer">《4.5 连接器、Skill、模板与对外入口》</a>。</p><h2 id="安装开源-skill-与-cli-工具-打通本地与终端能力" tabindex="-1">安装开源 Skill 与 CLI 工具：打通本地与终端能力 <a class="header-anchor" href="#安装开源-skill-与-cli-工具-打通本地与终端能力" aria-label="Permalink to &quot;安装开源 Skill 与 CLI 工具：打通本地与终端能力&quot;">​</a></h2><h3 id="资源边界" tabindex="-1">资源边界 <a class="header-anchor" href="#资源边界" aria-label="Permalink to &quot;资源边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">作用域</th><th style="text-align:left;">包含资源与配置</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>全局共享</strong></td><td style="text-align:left;">所有 Bot 共享已装 Skill、官方连接器、共用记忆与 <code>/workspace</code> 目录</td></tr><tr><td style="text-align:left;"><strong>独立持有</strong></td><td style="text-align:left;">各 Bot 独立持有专属工作指令、独立记忆片段与定时例程（Routines）</td></tr></tbody></table><p>体系结构梳理参见<a href="https://jcng5q8n0f3z.feishu.cn/wiki/XDkUwLJZxih7Dok0SKqcajKQn4e" target="_blank" rel="noreferrer">《4.5 连接器、Skill、模板与对外入口》</a>与<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Qw17wVBhJibhkpkAK6zceiMvned" target="_blank" rel="noreferrer">《Grok Bot Masterclass｜Avi Chawla》</a>。</p><h3 id="核心操作步骤" tabindex="-1">核心操作步骤 <a class="header-anchor" href="#核心操作步骤" aria-label="Permalink to &quot;核心操作步骤&quot;">​</a></h3><ol><li><p>开启本地网络流量中继。云电脑使用机房 IP，访问 GitHub 等外部站点容易被拦截。</p><p>在桌面端 Settings -&gt; Computer 勾选「流量经过本地设备」（Route traffic through this computer），借本机网络中继，客户端与云端需同步更新。</p></li><li><p>安装开源 Skill。在对话框直接发送仓库地址让 Bot 部署。如需 Access Token，等系统提示后通过安全卡片提交，<strong>严禁将 Token 直接粘贴在对话框中</strong>。</p></li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我安装这个开源 Skill：https://github.com/example/custom-data-skill</span></span>
<span class="line"><span>阅读仓库内的说明文档，将其注册为我的可用技能，并告诉我它支持的触发指令与所需参数。</span></span></code></pre></div><ol start="3"><li><p>独立登录 Codex CLI。先在网页端「账户安全与登录」打开「设备代码登录」（Device code login）。在云端终端运行登录命令，获取设备验证码并用本机浏览器验证。</p><p><strong>绝对不要把本机登录凭证复制到云电脑 <code>/workspace</code></strong>，否则共用缓存会导致 Token 刷新冲突、两端频繁掉线。</p></li><li><p>CLI 代理下放重型任务。大批量代码格式化或转码等机械任务，直接写成 Shell 脚本交给云电脑 CLI 执行。配合「Wake on Done」机制接收完成通知，避免 Bot 长时间占用高额度推理会话。</p></li></ol><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><ul><li>在云电脑终端执行 <code>codex --version</code> 正常输出版本信息，<strong>且本机终端日常使用不会被顶替掉线</strong>。</li><li>向 Bot 发送测试任务，能按流程在 <code>/workspace</code> 目录下生成符合交付标准的结构化文件。</li></ul><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><h3 id="插件与企业权限" tabindex="-1">插件与企业权限 <a class="header-anchor" href="#插件与企业权限" aria-label="Permalink to &quot;插件与企业权限&quot;">​</a></h3><ul><li>Zoom 授权报 4700 属官方重定向缺陷，客户端内无法修复。</li><li>Gmail 仅支持单账号绑定，换绑必须先断开当前邮箱再重授。</li><li>Google 权限审批<strong>必须搜「Grok」，不能搜「Cursor」</strong>，换浏览器没用。</li></ul><h3 id="专属邮箱与外发审批" tabindex="-1">专属邮箱与外发审批 <a class="header-anchor" href="#专属邮箱与外发审批" aria-label="Permalink to &quot;专属邮箱与外发审批&quot;">​</a></h3><ul><li><code>mail.grokbot.com</code> 无界面与推送，查信需问 Bot 或建例程；例程仅按发件人和域名监听（需过 SPF/DKIM），不能按主题筛选。</li><li>底层设有强行人闸，提示词无法跳过，发信必须在草稿<strong>手动点击「Send」</strong>。</li></ul><h3 id="安全与网络环境" tabindex="-1">安全与网络环境 <a class="header-anchor" href="#安全与网络环境" aria-label="Permalink to &quot;安全与网络环境&quot;">​</a></h3><ul><li>Teach a task 录屏长达 10 分钟且无 Secrets 掩码，别输入密码或展示 API Key。</li><li>所有 Bot 共用存储与登录态，<strong>机密文件别丢在 <code>/workspace</code></strong>。</li><li>拷本地 Token 会互相踢掉线，终端必须走设备码独立授权。</li><li>外部站点封机房 IP 报错，去 Computer 页面<strong>开启「流量经过本地设备」</strong>。</li></ul><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ol><li>侧边栏确认 Drive 和 Sheets 正常。让 Bot 找 Q3_Report 并用 Sheets 读表格 A1 到 B10，<strong>能读出且不报权限错</strong>。</li><li>用个人邮箱发带数字代码邮件到 <code>yourname@mail.grokbot.com</code>，等 2 分钟让 Bot 查收；让它起草回信，<strong>核对代码并点 Send 发出草稿卡片</strong>。</li><li>让 Bot 打印 <code>GITHUB_TOKEN</code>，<strong>必须拒绝明文或只给掩码</strong>；再跑测试命令能过鉴权，确认 Token 未泄漏。</li><li>搜 <code>@xai</code> 24 小时前两条高赞推文，<strong>原链接可点且没调第三方插件</strong>。</li><li>终端跑 <code>codex --version</code> 报版本；本地并发<strong>不冲突踢线</strong>；开「流量经过本地设备」能打开机房敏感页。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><h3 id="官方文档与支持页面" tabindex="-1">官方文档与支持页面 <a class="header-anchor" href="#官方文档与支持页面" aria-label="Permalink to &quot;官方文档与支持页面&quot;">​</a></h3><ul><li><a href="https://cursor.com/cn/help/grok-bot/connect-plugins.md" target="_blank" rel="noreferrer">连接插件</a></li><li><a href="https://cursor.com/cn/help/grok-bot/agent-email.md" target="_blank" rel="noreferrer">为你的 Bot 设置电子邮箱地址</a></li><li><a href="https://cursor.com/cn/help/grok-bot/secrets.md" target="_blank" rel="noreferrer">安全存储机密信息</a></li><li><a href="https://cursor.com/cn/help/grok-bot/computer-recovery.md" target="_blank" rel="noreferrer">Grok Bot 电脑</a></li><li><a href="https://cursor.com/cn/help/grok-bot/routines.md" target="_blank" rel="noreferrer">例程</a></li><li><a href="https://cursor.com/cn/help/grok-bot/team-bots.md" target="_blank" rel="noreferrer">团队 Bot</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/teams.md" target="_blank" rel="noreferrer">面向 Teams 和企业版的 Grok Bot</a></li></ul><h3 id="社区实战资料" tabindex="-1">社区实战资料 <a class="header-anchor" href="#社区实战资料" aria-label="Permalink to &quot;社区实战资料&quot;">​</a></h3><ul><li>《4.5 连接器、Skill、模板与对外入口》：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/XDkUwLJZxih7Dok0SKqcajKQn4e" target="_blank" rel="noreferrer">飞书知识库文档</a></li><li>《Grok Bot Masterclass｜Avi Chawla》：<a href="https://jcng5q8n0f3z.feishu.cn/wiki/Qw17wVBhJibhkpkAK6zceiMvned" target="_blank" rel="noreferrer">飞书知识库文档</a></li></ul>`,78)])])}const m=e(d,[["render",c]]);export{f as __pageData,m as default};
